fn check(
    shell: &impl ShellFormatting,
    name: &str,
    strings: &[StrCase],
    env: &[EnvCase],
    joins: &[JoinCase],
) {
    assert_eq!(shell.name(), name);
    let mut failures = Vec::new();
    for c in strings {
        if shell.escape(c.input) != c.escape {
            failures.push(format!(
                "{} escape {:?}: got {:?} want {:?}",
                c.group,
                c.input,
                shell.escape(c.input),
                c.escape
            ));
        }
        if shell.quote(c.input) != c.quote {
            failures.push(format!(
                "{} quote {:?}: got {:?} want {:?}",
                c.group,
                c.input,
                shell.quote(c.input),
                c.quote
            ));
        }
        if shell.needs_quoting(c.input) != c.needs_quoting {
            failures.push(format!(
                "{} needs_quoting {:?}: want {}",
                c.group, c.input, c.needs_quoting
            ));
        }
        if shell.format_path(c.input) != c.format_path {
            failures.push(format!("{} format_path {:?}", c.group, c.input));
        }
    }
    for c in env {
        if shell.env_var(c.input) != c.output {
            failures.push(format!(
                "env_var {:?}: got {:?} want {:?}",
                c.input,
                shell.env_var(c.input),
                c.output
            ));
        }
    }
    for c in joins {
        let args: Vec<String> = c.args.iter().map(|a| a.to_string()).collect();
        let got = shell.join(c.executable, &args);
        if got != c.output {
            failures.push(format!(
                "{} join {:?} {:?}: got {:?} want {:?}",
                c.group, c.executable, c.args, got, c.output
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} {} mismatches:\n{}",
        name,
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn fish_matches_ruby_oracle_bytes() {
    check(&Fish, FISH_NAME, FISH_STRINGS, FISH_ENV, FISH_JOIN);
}

#[test]
fn tcsh_matches_ruby_oracle_bytes() {
    check(&Tcsh, TCSH_NAME, TCSH_STRINGS, TCSH_ENV, TCSH_JOIN);
}

#[test]
fn tcsh_fuzz_weight_is_recorded() {
    let tcsh = TCSH_STRINGS.iter().filter(|c| c.group == "fuzz").count();
    let fish = FISH_STRINGS.iter().filter(|c| c.group == "fuzz").count();
    assert!(
        tcsh > fish,
        "tcsh fuzz {tcsh} must outweigh fish fuzz {fish}"
    );
    assert!(
        TCSH_JOIN.iter().filter(|c| c.group == "fuzz").count()
            > FISH_JOIN.iter().filter(|c| c.group == "fuzz").count()
    );
}
